# frozen_string_literal: true

require "minitest/autorun"
require "dependency_update"

class YarnLockfileTest < Minitest::Test
  LOCKFILE = <<~LOCK
    # THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.
    # yarn lockfile v1


    "@puppeteer/browsers@3.2.4":
      version "3.2.4"
      resolved "https://registry.yarnpkg.com/@puppeteer/browsers/-/browsers-3.2.4.tgz#abc"
      integrity sha512-browsers==
      dependencies:
        modern-tar "^0.8.5"
        semver "^7.7.2"

    "source-map-js@>=0.6.2 <2.0.0", source-map-js@^1.2.2:
      version "1.2.2"
      resolved "https://registry.yarnpkg.com/source-map-js/-/source-map-js-1.2.2.tgz#def"
      integrity sha512-sourcemap==

    modern-tar@^0.8.5:
      version "0.8.6"
      resolved "https://registry.yarnpkg.com/modern-tar/-/modern-tar-0.8.6.tgz#123"
      integrity sha512-new==
  LOCK

  def test_round_trips_unchanged
    assert_equal LOCKFILE, DependencyUpdate::YarnLockfile.new(LOCKFILE).to_s
  end

  def test_entry_fields
    entries = DependencyUpdate::YarnLockfile.new(LOCKFILE).entries

    assert_equal ["@puppeteer/browsers", "source-map-js", "modern-tar"], entries.map(&:name)
    assert_equal [">=0.6.2 <2.0.0", "^1.2.2"], entries[1].ranges
    assert_equal "0.8.6", entries[2].version
    assert_equal "https://registry.yarnpkg.com/modern-tar/-/modern-tar-0.8.6.tgz#123", entries[2].resolved
  end

  def test_dependency_names
    entries = DependencyUpdate::YarnLockfile.new(LOCKFILE).entries

    assert_equal ["modern-tar", "semver"], entries[0].dependency_names
    assert_empty entries[1].dependency_names
  end

  def test_dependency_names_unwraps_scoped_packages
    lockfile = DependencyUpdate::YarnLockfile.new(LOCKFILE)
    lockfile.entries.last.replace(
      version: "0.8.5", resolved: "https://registry.yarnpkg.com/x.tgz#1", integrity: nil,
      dependencies: { "@scope/pkg" => "^1.0.0" }, optional_dependencies: { "fsevents" => "~2.3.2" }
    )

    assert_equal ["@scope/pkg", "fsevents"], lockfile.entries.last.dependency_names
  end

  def test_replace_rewrites_only_that_entry
    lockfile = DependencyUpdate::YarnLockfile.new(LOCKFILE)
    lockfile.entries.last.replace(
      version: "0.8.5",
      resolved: "https://registry.yarnpkg.com/modern-tar/-/modern-tar-0.8.5.tgz#456",
      integrity: "sha512-old==",
      dependencies: { "zod" => "^4.0.0", "@scope/pkg" => "*" },
      optional_dependencies: nil
    )

    expected = LOCKFILE.sub(<<~OLD, <<~NEW)
      modern-tar@^0.8.5:
        version "0.8.6"
        resolved "https://registry.yarnpkg.com/modern-tar/-/modern-tar-0.8.6.tgz#123"
        integrity sha512-new==
    OLD
      modern-tar@^0.8.5:
        version "0.8.5"
        resolved "https://registry.yarnpkg.com/modern-tar/-/modern-tar-0.8.5.tgz#456"
        integrity sha512-old==
        dependencies:
          "@scope/pkg" "*"
          zod "^4.0.0"
    NEW
    assert_equal expected, lockfile.to_s
  end

  def test_wrap_follows_yarn_quoting
    assert_equal "sha512-abc+/=", DependencyUpdate::YarnLockfile.wrap("sha512-abc+/=")
    assert_equal '"1.2.3"', DependencyUpdate::YarnLockfile.wrap("1.2.3")
    assert_equal '"^1.2.3"', DependencyUpdate::YarnLockfile.wrap("^1.2.3")
    assert_equal '"@scope/pkg"', DependencyUpdate::YarnLockfile.wrap("@scope/pkg")
    assert_equal '"https://x/y"', DependencyUpdate::YarnLockfile.wrap("https://x/y")
    assert_equal '">=1 <2"', DependencyUpdate::YarnLockfile.wrap(">=1 <2")
  end
end
